from collections import deque
R,C=len(grid),len(grid[0]); seen=set(); comps=[]
for r in range(R):
 for c in range(C):
  if grid[r][c] not in (0,2) and (r,c) not in seen:
   color=grid[r][c]; q=[(r,c)]; seen.add((r,c)); comp=[]
   while q:
    p=q.pop();comp.append(p)
    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
     n=(p[0]+dr,p[1]+dc)
     if 0<=n[0]<R and 0<=n[1]<C and n not in seen and grid[n[0]][n[1]]==color:
      seen.add(n);q.append(n)
   comps.append((color,comp))
print([(co, sorted(p)) for co,p in comps])
